// src/pages/DSLoaiSanPham.tsx

import React from 'react';
import { Table, Button, Input, Space, Tag } from 'antd';
import { EditOutlined, DeleteOutlined, PlusOutlined, SearchOutlined } from '@ant-design/icons';

const { Search } = Input;

// 1. Dữ liệu mẫu
interface LoaiSanPham {
    id: number;
    tenLoai: string;
    mota: string;
}

const dataSource: LoaiSanPham[] = [
    { id: 1, tenLoai: 'Đồ uống' },
    { id: 2, tenLoai: 'Đồ ăn vặt' },
    { id: 3, tenLoai: 'Kem' },
    { id: 4, tenLoai: 'Cà phê' },
    { id: 5, tenLoai: 'Trà sữa' },
];

// 2. Cấu hình các cột cho Table
const columns = [
    {
        title: 'ID',
        dataIndex: 'id',
        key: 'id',
        width: 80,
    },
    {
        title: 'Tên loại',
        dataIndex: 'tenLoai',
        key: 'ten_loai',
    },
        {
        title: 'Mô tả',
        dataIndex: 'tenLoai',
        key: 'mo_ta',
    },
    {
        title: 'Chức năng',
        key: 'action',
        width: 150,
        render: (_: any, record: LoaiSanPham) => (
            <Space size="small">
                <Button 
                    type="primary" 
                    style={{ backgroundColor: '#333', borderColor: '#333' }}
                    size="small"
                >
                    Sửa
                </Button>
                <Button 
                    type="primary" 
                    danger 
                    size="small"
                >
                    Xóa
                </Button>
            </Space>
        ),
    },
];

const DSLoaiSanPham: React.FC = () => {
    
    const onSearch = (value: string) => {
        console.log('Đang tìm kiếm:', value);

    };
    
    const handleAdd = () => {
        console.log('Mở form Thêm Loại sản phẩm mới');
    };

    return (
        <div style={{ padding: 0 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
                <h2>Quản lý Loại sản phẩm</h2>
                <Button 
                    type="primary" 
                    icon={<PlusOutlined />} 
                    onClick={handleAdd}
                >
                    Thêm Loại sản phẩm
                </Button>
            </div>
            
            {/* 1. Thanh tìm kiếm */}
            <div style={{ marginBottom: 20 }}>
                <Search
                    placeholder="Tên loại sản phẩm cần tìm"
                    allowClear
                    enterButton={<SearchOutlined />} 
                    onSearch={onSearch}
                    style={{ maxWidth: 400 }} 
                />
            </div>
            
            {/* 2. Bảng hiển thị danh sách */}
            <Table
                pagination={{ 
                    position: ['bottomCenter'], 
                    pageSize: 10,
                    showSizeChanger: false, 
                    total: dataSource.length,
                    showTotal: (total, range) => `${range[0]}-${range[1]} trên tổng ${total} mục`,
                }}
                dataSource={dataSource}
                columns={columns}
                rowKey="id"
            />
        </div>
    );
};

export default DSLoaiSanPham;
